// Clasa ne descrie un concept incomplet  nu poate fi initializatapublic abstract class Task {    private String taskID;    private String description;    Task(String id,String desc){        this.taskID = id;        this.description = desc;    }    public abstract void execute();    public String toString(){        return taskID + description;    }    @Override    public boolean equals(Object obj){        if (this == obj){            return true;        }        if ( obj == null || getClass() != obj.getClass()) return false;        Task task = (Task)obj;        return Objects.equals(task.taskID,this.taskID);    }    @Override    public int hashCode(){        return Objects.hashCode(taskID);    }}